// Normalises whatever a buyer's agent sends, then emits one item per package
// so the HTTP node downstream fans out over them.
//
// There is no single shape to expect. The same request, phrased the same way by
// the same model, arrives as a top-level name and version, as a list of
// objects, as a package.json map, or as "lodash@4.17.20". A paid worker is a
// public API with no docs and no support channel, so being liberal here is the
// job, not sloppiness.

const body = $input.first().json.body || {};
const input = body.input ?? body ?? {};

const ver = (v) => String(v).replace(/^[\^~>=<\s]+/, '').replace(/\s.*$/, '').trim();

function one(entry, key) {
  if (entry == null) return null;
  if (typeof entry === 'string') {
    if (key) return { name: key, version: ver(entry) };
    const m = entry.trim().match(/^(@?[\w./-]+?)[@\s]+v?([\d][\w.+-]*)$/);
    return m ? { name: m[1], version: m[2] } : { name: entry.trim(), version: 'latest' };
  }
  if (typeof entry === 'object') {
    const name = entry.name || entry.package || entry.id || key;
    if (!name) return null;
    return { name: String(name), version: ver(entry.version || entry.range || entry.v || 'latest') };
  }
  return null;
}

function collect(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v.map((e) => one(e, null));
  if (typeof v === 'object') return Object.entries(v).map(([k, e]) => one(e, k));
  if (typeof v === 'string') return [one(v, null)];
  return [];
}

let pkgs = [];
if (input.packages !== undefined) pkgs = collect(input.packages);
else if (input.dependencies !== undefined) pkgs = collect(input.dependencies);
else if (input.deps !== undefined) pkgs = collect(input.deps);
else if (Array.isArray(input)) pkgs = collect(input);
else if (input.name || input.package) pkgs = [one(input, null)];
else if (typeof input === 'string') pkgs = collect(input);

pkgs = pkgs
  .filter((p) => p && p.name && !/^\d+$/.test(p.name))
  .map((p) => ({ name: String(p.name), version: String(p.version || 'latest') }))
  .slice(0, 25);

if (!pkgs.length) {
  throw new Error(
    'No packages found. Accepted: {"input":{"name":"lodash","version":"4.17.20"}}, ' +
    '{"input":{"dependencies":[{"name","version"}]}}, ' +
    '{"input":{"dependencies":{"lodash":"^4.17.20"}}}, ' +
    '{"input":{"packages":["lodash@4.17.20"]}}. ' +
    'Received: ' + JSON.stringify(input).slice(0, 250)
  );
}

// npm serves a scoped name with the slash percent-encoded, and nowhere else.
return pkgs.map((p) => ({ json: {
  name: p.name,
  version: p.version,
  url: 'https://registry.npmjs.org/' + p.name.replace('/', '%2f') + '/' + encodeURIComponent(p.version),
} }));

const asked = $('Read the request').all().map((i) => i.json);
const got = $input.all().map((i) => i.json);

if (got.length !== asked.length) {
  throw new Error(
    'The registry answered for ' + got.length + ' of ' + asked.length + ' packages. ' +
    'Refusing to report a partial audit as a complete one.'
  );
}

// Categories, not opinions. What counts as acceptable depends on what the buyer
// is shipping, so this reports the obligation and lets them decide. Saying
// "GPL is bad" would be wrong for half the people asking.
const STRONG = /^(A?GPL|SSPL|OSL|EUPL|CPAL)/i;
const WEAK = /^(LGPL|MPL|EPL|CDDL|MS-RL)/i;
const PERMISSIVE = /^(MIT|ISC|BSD|Apache|Unlicense|0BSD|Zlib|CC0|WTFPL|Python-2)/i;

function classify(raw) {
  if (!raw) return { category: 'unknown', obligation: 'No license field published. Treat as all rights reserved until the maintainer clarifies.' };
  const id = String(typeof raw === 'object' ? (raw.type || raw.name || '') : raw).trim();
  if (!id) return { category: 'unknown', obligation: 'No license field published. Treat as all rights reserved until the maintainer clarifies.' };
  if (STRONG.test(id)) return { category: 'strong-copyleft', obligation: 'Distributing linked code may require releasing your source under the same license.' };
  if (WEAK.test(id)) return { category: 'weak-copyleft', obligation: 'Modifications to this package must usually be published; your own code generally need not be.' };
  if (PERMISSIVE.test(id)) return { category: 'permissive', obligation: 'Attribution, and keep the license text. No source obligation.' };
  return { category: 'other', obligation: 'Not a common identifier. Read the license before shipping.' };
}

const results = asked.map((a, i) => {
  const r = got[i] || {};
  // A 404 arrives as an error body rather than a throw, because the HTTP node
  // is set to continue: one unpublished version must not void the whole audit.
  const missing = !r.name || r.error;
  const id = missing ? null : (typeof r.license === 'object' ? (r.license.type || r.license.name || null) : r.license || null);
  const c = classify(id);
  return {
    package: a.name,
    version: missing ? a.version : (r.version || a.version),
    license: id,
    category: missing ? 'not-found' : c.category,
    obligation: missing
      ? 'This package or version is not on the npm registry, so nothing could be checked.'
      : c.obligation,
    deprecated: missing ? null : (typeof r.deprecated === 'string' ? r.deprecated : !!r.deprecated),
    homepage: missing ? null : (r.homepage || null),
  };
});

const flagged = results.filter((r) => r.category === 'strong-copyleft' || r.category === 'weak-copyleft');
const unknown = results.filter((r) => r.category === 'unknown' || r.category === 'not-found');

return [{ json: { output: {
  scanned: results.length,
  copyleft: flagged.length,
  unknown: unknown.length,
  // Said plainly so a buyer's agent does not turn a categorisation into legal
  // advice it is not qualified to give.
  verdict: flagged.length === 0 && unknown.length === 0
    ? 'All dependencies are permissively licensed.'
    : 'Some dependencies carry source obligations or publish no license. Review before shipping proprietary software.',
  licenses: results,
  source: 'registry.npmjs.org',
  note: 'A categorisation of published license identifiers, not legal advice.',
  checkedAt: new Date().toISOString(),
} } }];
